        , cast(null as varchar) as ADDRESS_LINE_3
        , cast(null as varchar) as DISTRICT
        , 'BJAZ_HM_MEMBER_HLTH_DTLS' as RECORD_SOURCE
        , 'opus_health_v2' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hm_member_hlth_dtls') }}
    where (md5(normalise(upper(nullif(coalesce(nullif(trim(HAT_ID_CITY),''),'') || '|' || coalesce(nullif(trim(HAT_ID_STATE),''),''), '|'))))) is not null
    union all
    select
        md5(upper('HUB_LOCATION|' || (HUB_LOCATION_BK__ADDRESS_1_ADDRESS_2_PINCODE))) as HUB_LOCATION_HK
        , ADDRESS_1 as ADDRESS_LINE_1
        , cast(null as varchar) as LOCALITY
        , cast(null as varchar) as CITY
        , cast(null as varchar) as STATE_NAME
        , PINCODE as POSTAL_CODE
        , cast(null as varchar) as COUNTRY_NAME
        , cast(null as varchar) as POST_OFFICE_NAME
        , ADDRESS_2 as ADDRESS_LINE_2
        , cast(null as varchar) as STATE_CODE
        , cast(null as varchar) as BUILDING_NAME
        , cast(null as varchar) as STREET_NAME
        , cast(null as varchar) as VILLAGE
        , cast(null as varchar) as COUNTRY_CODE
        , cast(null as varchar) as LANDMARK
        , cast(null as varchar) as ADDRESS_LINE_3
        , cast(null as varchar) as DISTRICT
        , 'BJAZ_PMSBY_DATA_WEB_SERVICE' as RECORD_SOURCE
        , 'opus_health_v2' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_pmsby_data_web_service') }}
    where (md5(normalise(upper(nullif(trim( coalesce(ADDRESS_1,'') || ' ' || coalesce(ADDRESS_2,'') || ' ' || coalesce(PINCODE,'') ),''))))) is not null
    union all
    select
        md5(upper('HUB_LOCATION|' || (HUB_LOCATION_BK__BRANCH_ADDRESS))) as HUB_LOCATION_HK
        , BRANCH_ADDRESS as ADDRESS_LINE_1
        , cast(null as varchar) as LOCALITY
        , cast(null as varchar) as CITY
        , STATE as STATE_NAME
        , cast(null as varchar) as POSTAL_CODE
        , cast(null as varchar) as COUNTRY_NAME
        , cast(null as varchar) as POST_OFFICE_NAME
        , cast(null as varchar) as ADDRESS_LINE_2
        , cast(null as varchar) as STATE_CODE
        , cast(null as varchar) as BUILDING_NAME
        , cast(null as varchar) as STREET_NAME
        , cast(null as varchar) as VILLAGE
        , cast(null as varchar) as COUNTRY_CODE
        , cast(null as varchar) as LANDMARK
        , cast(null as varchar) as ADDRESS_LINE_3
        , DISTRICT as DISTRICT
        , 'BJAZ_NEFT_IFSC_MASTER' as RECORD_SOURCE
        , 'opus_health_v2' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_neft_ifsc_master') }}
    where (md5(normalise(upper(nullif(trim(BRANCH_ADDRESS),''))))) is not null
    union all
    select
        md5(upper('HUB_LOCATION|' || (HUB_LOCATION_BK__pincode))) as HUB_LOCATION_HK
        , cast(null as varchar) as ADDRESS_LINE_1
        , cast(null as varchar) as LOCALITY
        , cast(null as varchar) as CITY
        , cast(null as varchar) as STATE_NAME
        , pincode as POSTAL_CODE
        , cast(null as varchar) as COUNTRY_NAME
        , cast(null as varchar) as POST_OFFICE_NAME
        , cast(null as varchar) as ADDRESS_LINE_2
        , cast(null as varchar) as STATE_CODE
        , cast(null as varchar) as BUILDING_NAME
        , cast(null as varchar) as STREET_NAME
        , cast(null as varchar) as VILLAGE
        , cast(null as varchar) as COUNTRY_CODE
        , cast(null as varchar) as LANDMARK
        , cast(null as varchar) as ADDRESS_LINE_3
        , cast(null as varchar) as DISTRICT
        , 'BJAZ_BOT_UTILIZATION_DTLS' as RECORD_SOURCE
        , 'opus_health_delta3' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_bot_utilization_dtls') }}
    where (md5(normalise(upper(nullif(trim(pincode),''))))) is not null
    union all
    select
        md5(upper('HUB_LOCATION|' || (HUB_LOCATION_BK__ADDRESS1_ADDRESS2_ADDRESS3_CITY_STATE_PIN_CODE))) as HUB_LOCATION_HK
        , ADDRESS1 as ADDRESS_LINE_1
        , cast(null as varchar) as LOCALITY
        , CITY as CITY
        , STATE as STATE_NAME
        , PIN_CODE as POSTAL_CODE
        , cast(null as varchar) as COUNTRY_NAME
        , cast(null as varchar) as POST_OFFICE_NAME
        , ADDRESS2 as ADDRESS_LINE_2
        , cast(null as varchar) as STATE_CODE
        , cast(null as varchar) as BUILDING_NAME
        , cast(null as varchar) as STREET_NAME
        , cast(null as varchar) as VILLAGE
        , cast(null as varchar) as COUNTRY_CODE
        , cast(null as varchar) as LANDMARK
        , ADDRESS3 as ADDRESS_LINE_3
        , cast(null as varchar) as DISTRICT
        , 'BJAZ_REMEDINET_PATIENT_DETAILS' as RECORD_SOURCE
        , 'opus_health_delta3' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_remedinet_patient_details') }}
    where (md5(normalise(upper(nullif(coalesce(nullif(trim(ADDRESS1),''),'') || '|' || coalesce(nullif(trim(ADDRESS2),''),'') || '|' || coalesce(nullif(trim(ADDRESS3),''),'') || '|' || coalesce(nullif(trim(CITY),''),'') || '|' || coalesce(nullif(trim(STATE),''),'') || '|' || coalesce(nullif(trim(PIN_CODE),''),''), '|||||'))))) is not null
    union all
    select
        md5(upper('HUB_LOCATION|' || (HUB_LOCATION_BK__MAILING_PINCODE))) as HUB_LOCATION_HK
        , ADDRESS as ADDRESS_LINE_1
        , cast(null as varchar) as LOCALITY
        , CITY as CITY
        , cast(null as varchar) as STATE_NAME
        , PINCODE as POSTAL_CODE
        , cast(null as varchar) as COUNTRY_NAME
        , cast(null as varchar) as POST_OFFICE_NAME
        , cast(null as varchar) as ADDRESS_LINE_2
        , cast(null as varchar) as STATE_CODE
        , cast(null as varchar) as BUILDING_NAME
        , cast(null as varchar) as STREET_NAME
        , cast(null as varchar) as VILLAGE
        , cast(null as varchar) as COUNTRY_CODE
        , cast(null as varchar) as LANDMARK
        , cast(null as varchar) as ADDRESS_LINE_3
        , cast(null as varchar) as DISTRICT
        , 'BJAZ_POLICY_SUMMARY' as RECORD_SOURCE
        , 'opus_health_delta3' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_policy_summary') }}
    where (md5(normalise(upper(nullif(trim(MAILING_PINCODE),''))))) is not null
    union all
    select
        md5(upper('HUB_LOCATION|' || (HUB_LOCATION_BK__MAILING_PINCODE))) as HUB_LOCATION_HK
        , PREV_INSURER_ADD as ADDRESS_LINE_1
        , cast(null as varchar) as LOCALITY
        , cast(null as varchar) as CITY
        , cast(null as varchar) as STATE_NAME
        , MAILING_PINCODE as POSTAL_CODE
        , cast(null as varchar) as COUNTRY_NAME
        , cast(null as varchar) as POST_OFFICE_NAME
        , cast(null as varchar) as ADDRESS_LINE_2
        , cast(null as varchar) as STATE_CODE
        , cast(null as varchar) as BUILDING_NAME
        , cast(null as varchar) as STREET_NAME
        , cast(null as varchar) as VILLAGE
        , cast(null as varchar) as COUNTRY_CODE
        , cast(null as varchar) as LANDMARK
        , cast(null as varchar) as ADDRESS_LINE_3
        , cast(null as varchar) as DISTRICT
        , 'BJAZ_POLICY_BASES_EXTN' as RECORD_SOURCE
        , 'opus_health_delta3' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_policy_bases_extn') }}
    where (md5(normalise(upper(nullif(trim(MAILING_PINCODE),''))))) is not null
),

resolved as (
    select
        HUB_LOCATION_HK,
        coalesce(max(case when SOURCE_RUN = 'opus_health_v2' then ADDRESS_LINE_1 end),
                 max(case when SOURCE_RUN = 'opus_health_legacy_v4' then ADDRESS_LINE_1 end),
                 max(case when SOURCE_RUN = 'opus_health_delta3' then ADDRESS_LINE_1 end)) as ADDRESS_LINE_1,
        coalesce(max(case when SOURCE_RUN = 'opus_health_v2' then LOCALITY end),
                 max(case when SOURCE_RUN = 'opus_health_legacy_v4' then LOCALITY end)) as LOCALITY,
        coalesce(max(case when SOURCE_RUN = 'opus_health_v2' then CITY end),
                 max(case when SOURCE_RUN = 'opus_health_legacy_v4' then CITY end),
                 max(case when SOURCE_RUN = 'opus_health_delta3' then CITY end)) as CITY,
        coalesce(max(case when SOURCE_RUN = 'opus_health_v2' then STATE_NAME end),
                 max(case when SOURCE_RUN = 'opus_health_legacy_v4' then STATE_NAME end),
                 max(case when SOURCE_RUN = 'opus_health_delta3' then STATE_NAME end)) as STATE_NAME,
        coalesce(max(case when SOURCE_RUN = 'opus_health_v2' then POSTAL_CODE end),
                 max(case when SOURCE_RUN = 'opus_health_legacy_v4' then POSTAL_CODE end),
                 max(case when SOURCE_RUN = 'opus_health_delta3' then POSTAL_CODE end)) as POSTAL_CODE,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then COUNTRY_NAME end) as COUNTRY_NAME,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then POST_OFFICE_NAME end) as POST_OFFICE_NAME,
        coalesce(max(case when SOURCE_RUN = 'opus_health_v2' then ADDRESS_LINE_2 end),
                 max(case when SOURCE_RUN = 'opus_health_legacy_v4' then ADDRESS_LINE_2 end),
                 max(case when SOURCE_RUN = 'opus_health_delta3' then ADDRESS_LINE_2 end)) as ADDRESS_LINE_2,
        coalesce(max(case when SOURCE_RUN = 'opus_health_v2' then STATE_CODE end),
                 max(case when SOURCE_RUN = 'opus_health_legacy_v4' then STATE_CODE end)) as STATE_CODE,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then BUILDING_NAME end) as BUILDING_NAME,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then STREET_NAME end) as STREET_NAME,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then VILLAGE end) as VILLAGE,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then COUNTRY_CODE end) as COUNTRY_CODE,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then LANDMARK end) as LANDMARK,
        coalesce(max(case when SOURCE_RUN = 'opus_health_v2' then ADDRESS_LINE_3 end),
                 max(case when SOURCE_RUN = 'opus_health_delta3' then ADDRESS_LINE_3 end)) as ADDRESS_LINE_3,
        max(case when SOURCE_RUN = 'opus_health_v2' then DISTRICT end) as DISTRICT,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_LOCATION_HK
),

hashed as (
    select
        *,
        case when ADDRESS_LINE_1 is not null or LOCALITY is not null or CITY is not null or STATE_NAME is not null or POSTAL_CODE is not null or COUNTRY_NAME is not null or POST_OFFICE_NAME is not null or ADDRESS_LINE_2 is not null or STATE_CODE is not null or BUILDING_NAME is not null or STREET_NAME is not null or VILLAGE is not null or COUNTRY_CODE is not null or LANDMARK is not null or ADDRESS_LINE_3 is not null or DISTRICT is not null
                     then md5(upper(coalesce(cast(ADDRESS_LINE_1 as varchar), '') || '|' || coalesce(cast(LOCALITY as varchar), '') || '|' || coalesce(cast(CITY as varchar), '') || '|' || coalesce(cast(STATE_NAME as varchar), '') || '|' || coalesce(cast(POSTAL_CODE as varchar), '') || '|' || coalesce(cast(COUNTRY_NAME as varchar), '') || '|' || coalesce(cast(POST_OFFICE_NAME as varchar), '') || '|' || coalesce(cast(ADDRESS_LINE_2 as varchar), '') || '|' || coalesce(cast(STATE_CODE as varchar), '') || '|' || coalesce(cast(BUILDING_NAME as varchar), '') || '|' || coalesce(cast(STREET_NAME as varchar), '') || '|' || coalesce(cast(VILLAGE as varchar), '') || '|' || coalesce(cast(COUNTRY_CODE as varchar), '') || '|' || coalesce(cast(LANDMARK as varchar), '') || '|' || coalesce(cast(ADDRESS_LINE_3 as varchar), '') || '|' || coalesce(cast(DISTRICT as varchar), '')))
                end as SAT_COMMON_ADDRESS_HASHDIFF
    from resolved
)

select * from hashed
where HUB_LOCATION_HK is not null
  and SAT_COMMON_ADDRESS_HASHDIFF is not null
